"""Build a dependency-free static showcase from the reviewed inventory."""
import json
import shutil
from html import escape as e
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def build():
    inventory = json.loads((ROOT / 'showcase/projects.json').read_text(encoding='utf-8'))
    cards = []
    for p in inventory['projects']:
        cards.append(f'''<article class="project" id="project-{p['id']}">
<div class="project-top"><span class="number">{p['id']}</span><span class="access">{'Bundled employer source'}</span></div>
<h3>{e(p['title'])}</h3><p><strong>Problem</strong> {e(p['problem'])}</p><p><strong>Implementation</strong> {e(p['implementation'])}</p>
<ul class="tags">{''.join('<li>'+e(s)+'</li>' for s in p['skills'])}</ul>
<div class="links"><a href="{e(p.get('employer_source', p['source']))}">Bundled source ↗</a><a href="{e(p['ci'])}">Recorded CI ↗</a><a href="../{e(p['evidence'])}">Evidence ↗</a></div>
<details><summary>Verification and limits</summary><p>Recorded {e(p['verified_at'][:10])} · commit <code>{p['commit']}</code></p><p>{e(p['limitation'])}</p></details></article>''')
    html = '''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="Eight AI systems engineering projects, verifiable evidence, and a guided hands-on operations demo.">
<title>GitHub Project Showcase with a Guided Hands-On Demo</title><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="#start">AI SYSTEMS<br><span>ENGINEERING LAB</span></a><nav aria-label="Main navigation"><a href="#projects">Projects</a><a href="#demo">Guided demo</a><a href="#evidence">Evidence</a></nav><a class="github" href="https://github.com/texasbredmj/ai-engineering-portfolio">GitHub ↗</a></header>
<main id="main"><section class="hero" id="start"><div><p class="eyebrow">ENGINEERING PORTFOLIO / 2026</p><h1>Build the task.<br>Verify the outcome.</h1><p class="intro">AI systems need more than a success message. Explore eight projects that execute authorized work, recover from failures, and independently check what actually happened.</p><p class="subtle">GitHub Project Showcase with a Guided Hands-On Demo</p><div class="actions"><a class="button primary" href="#projects">Explore Projects <span>↓</span></a><a class="button" href="#demo">Try the Demo</a><a class="text-link" href="#evidence">Inspect Evidence ↗</a></div></div><aside class="hero-note"><span class="status-dot"></span><p>FIRST HANDS-ON DEMO</p><h2>Agent Operations<br>Control Center</h2><p>React dashboard<br>FastAPI authorization<br>PostgreSQL receipts</p><a href="#demo">Follow the five-minute walkthrough →</a><small>Setup time is additional.</small></aside></section>
<figure class="dashboard"><div class="figure-bar"><span>RELAY / OPERATIONS CONTROL CENTER</span><span>Earlier standalone dashboard capture</span></div><img src="assets/dashboard-desktop.png" width="1440" height="960" alt="Recorded Relay application dashboard with task states and operational metrics"><figcaption>Real application capture from Project 08. The showcase and real dashboard are connected in the local employer build; use Open running dashboard to create and control tasks.</figcaption></figure>
<section class="section" id="projects"><div class="section-heading"><div><p class="eyebrow">01 / PROJECT MAP</p><h2>Eight projects.<br>One engineering discipline.</h2></div><p>The live workflow connects Projects 02, 03, 06 and 08. Maintenance, evaluation, recovery and release projects have their own runnable demonstrations. Earlier CI links identify the original recorded commits.</p></div><div class="projects">PROJECT_CARDS</div></section>
<section class="section" id="demo"><div class="section-heading"><div><p class="eyebrow">02 / GUIDED HANDS-ON DEMO</p><h2>Operate it.<br>Then inspect the proof.</h2></div><p>Five minutes after setup. Perform each action in the real application, then use the checklist to track your own progress.</p></div>
<div class="actions"><a class="button primary" id="dashboard-link" href="https://codespaces.new/texasbredmj/ai-engineering-portfolio?quickstart=1">Launch GitHub demo ↗</a><a class="button" href="docs/EMPLOYER-TEST.md">Launch instructions</a><a class="text-link" href="https://github.com/texasbredmj/ai-engineering-portfolio/actions/workflows/integrated-platform.yml">Integration delivery checks ↗</a></div><details class="setup" open><summary>Start the real application</summary><p>Open the <a href="https://github.com/texasbredmj/ai-engineering-portfolio#start-here">GitHub portfolio</a> and launch its Codespace. Setup starts PostgreSQL, Temporal, the tool gateway, model gateway, worker and dashboard automatically.</p><p>Open <code>.platform/DEMO-ACCESS.md</code> in the Codespace editor for your generated role tokens. Open private port 18780. This showcase is at <code>/showcase/</code>; the dashboard is at <code>/</code>.</p><p>The integrated workflow performs real database effects through the gateways. Local mock providers avoid paid model calls. Test results are available in the repository's integration workflow and in the dashboard's Project evidence view.</p><a href="../docs/EMPLOYER-TEST.md">Full employer walkthrough ↗</a></details>
<div class="progress-line"><p id="progress" role="status" aria-live="polite">0 of 5 steps marked complete</p><button id="reset" type="button">Reset checklist</button></div>
<ol class="walkthrough">
<li><label><input type="checkbox" data-step="1"><span>01 / Execution and independent verification</span></label><h3>Create a task. Inspect its receipt.</h3><p>Sign in as operator. Choose <strong>+ New task → Inventory reservation</strong>, use quantity 2, and submit. Find the task under Completed tasks and open Evidence.</p><p class="expected"><strong>Expected</strong> SUCCEEDED, verified=true, observed_quantity=2.</p></li>
<li><label><input type="checkbox" data-step="2"><span>02 / Backend authorization and human oversight</span></label><h3>Make an approval decision.</h3><p>As operator, create a Reservation requiring approval. Record its ID. Sign out, sign in as approver, find it in Pending approvals and approve with a reason. Try rejection on a separate task.</p><p class="expected"><strong>Expected</strong> PENDING_APPROVAL until the approver acts. Approval produces verified completion; rejection produces REJECTED without an effect. Operator and viewer cannot approve.</p></li>
<li><label><input type="checkbox" data-step="3"><span>03 / Recovery and bounded retries</span></label><h3>Recover a temporary failure.</h3><p>As operator, create Temporary failure → eligible retry. After FAILED, inspect the task, choose Retry, supply a reason and confirm.</p><p class="expected"><strong>Expected</strong> SUCCEEDED on attempt 2 with a verified receipt.</p></li>
<li><label><input type="checkbox" data-step="4"><span>04 / Evaluation and false-success detection</span></label><h3>Investigate the mismatch.</h3><p>Create Receipt mismatch → investigation with quantity 2. Compare the tool claim in Tools with independent verification in Evidence.</p><p class="expected"><strong>Expected</strong> FAILED and verified=false despite the tool's completion claim. Quantity differs; retry is ineligible.</p></li>
<li><label><input type="checkbox" data-step="5"><span>05 / Observability and operations</span></label><h3>Follow the execution trail.</h3><p>Inspect Workflow, Tools and Traces for a task. Then open Execution traces, Reliability metrics, Resource usage and Cost reports.</p><p class="expected"><strong>Expected</strong> Matching task trace IDs and inspectable history. Paid model calls remain zero. Reported mock-provider token usage and simulated cost are visible separately; shared worker resource counters are identified.</p></li></ol><p class="subtle">Checklist marks are self-reported and last only for this page session. They do not execute backend actions or verify results.</p>
<div class="notice"><strong>One GitHub launch path.</strong><p>GitHub is the employer entry point. Its Codespace runs this showcase and the real backend at one forwarded port. Integration validation is in progress; check the delivery workflow for the current result.</p></div></section>
<section class="section evidence" id="evidence"><p class="eyebrow">03 / ENGINEERING EVIDENCE</p><h2>Claims you can inspect.</h2><div class="evidence-grid"><div><h3>Architecture and authorization</h3><p>React and FastAPI enforce role and project authorization. The dashboard dispatches the real Temporal workflow, which calls the tool and model gateways. Independent PostgreSQL ledger verification controls completion; reports, workflow history and traces remain inspectable.</p><a href="https://github.com/texasbredmj/agent-operations-control-center/blob/2147f79a6c2bc5ca89e0134f137ed5ee5e411f17/docs/architecture.md">Inspect architecture ↗</a><br><a href="https://github.com/texasbredmj/agent-operations-control-center/blob/2147f79a6c2bc5ca89e0134f137ed5ee5e411f17/docs/threat-model.md">Inspect security decisions ↗</a></div><div><h3>Recorded verification</h3><p>Project 08's recorded delivery has a 35-test suite run on host and installed wheel, eight HTTP scenarios, eight Chromium scenarios and restart checks. The test runs are the same suite, not 70 unique tests.</p><a href="../evidence/project08.json">Read preserved results ↗</a><br><a href="https://github.com/texasbredmj/agent-operations-control-center/actions/runs/38527430319">Inspect recorded CI ↗</a></div><div><h3>Failure and scope</h3><p>Temporary failure, rejection and receipt mismatch are deliberate scenarios. The integrated workflow uses generated role tokens and local mock model providers, with zero paid model calls. Supporting projects run real maintenance, evaluation, recovery and release checks. Production identity and arbitrary external API guarantees remain outside scope.</p><a href="../docs/FOUNDATION.md">Read section gates and evidence limits ↗</a></div></div></section>
<section class="section contribution"><p class="eyebrow">04 / ENGINEERING CONTRIBUTION</p><h2>Decisions worth discussing.</h2><p>The system combines task controls, server-enforced permissions and independent receipt checks. Personal design, implementation and testing attribution, AI assistance, and lessons learned need owner review before the resume is published.</p><div class="tradeoffs"><p><strong>Reproducibility vs. realism.</strong> A deterministic database effect makes verification and recovery repeatable; its guarantees stop at that fixture boundary.</p><p><strong>Simple setup vs. production identity.</strong> Separate generated role tokens demonstrate backend authorization; production requires credential expiry, rotation and an identity provider.</p></div><a href="../resume/2026.md">Review the 2026 resume draft ↗</a></section></main>
<footer><span>AI SYSTEMS ENGINEERING LAB / 2026</span><a href="../docs/DEVELOPMENT-WORKFLOW.md">Development evidence workflow ↗</a><span>GitHub delivery candidate · verify integration checks</span></footer></body></html>'''
    # Package supporting evidence with the site so publishing site/ keeps links intact.
    html = html.replace('PROJECT_CARDS', '\n'.join(cards)).replace('href="../', 'href="')
    (ROOT / 'site/index.html').write_text(html, encoding='utf-8')
    for folder in ('docs', 'evidence', 'resume'):
        shutil.copytree(ROOT / folder, ROOT / 'site' / folder, dirs_exist_ok=True)
    print(f'Built static showcase: {len(cards)} evidence-linked project cards.')


if __name__ == '__main__':
    build()
